// Interface
public interface Precificacao {
    double calcularValorTotal(Notebook notebook, int horasUtilizadas);
}

// Estratégia por Dia
public class PrecificacaoPorDia implements Precificacao {
    @Override
    public double calcularValorTotal(Notebook notebook, int horasUtilizadas) {
        double dias = Math.ceil(horasUtilizadas / 24d);
        return notebook.getPrecoPorDia() * dias;
    }
}

// Estratégia por Hora
public class PrecificacaoPorHora implements Precificacao {
    @Override
    public double calcularValorTotal(Notebook notebook, int horasUtilizadas) {
        return notebook.getPrecoPorHora() * horasUtilizadas;
    }
}
